// Usage: node bot/ask.mjs [prompt]
// Reads HAMMERSTEIN_URL from env (default: http://localhost:11434)
export async function ask(prompt, opts = {}) {
  const url = process.env.HAMMERSTEIN_URL ?? 'http://localhost:11434/api/chat';
  const res = await fetch(url, { method: 'POST', body: JSON.stringify({model: 'hammerstein', messages: [{role:'user',content:prompt}]}) });
  return await res.json();
